function strings(lang) {
  const i = Math.max(0, ORDER.indexOf(lang));
  const en = ORDER.indexOf('en');
  const out = {};
  for (const [k, arr] of Object.entries(T)) out[k] = arr[i] || arr[en];
  return out;
}

function langInfo(lang) { return LANGS.find((l) => l.code === lang) || LANGS[0]; }

module.exports = { LANGS, strings, langInfo };
